import{_ as i,C as e,o as c,c as u,j as t,a,E as g}from"./chunks/framework.Bf1r8NYr.js";const d=JSON.parse('{"title":"Quiz — Bài 4","description":"","frontmatter":{"quizKey":"module-4-quality","questions":[{"id":"4.1.","text":"Trong các chiều chất lượng dữ liệu, “plausibility” nghĩa là gì?","options":[{"key":"A","text":"Dữ liệu có đủ số dòng và đủ trường theo thiết kế nghiên cứu."},{"key":"B","text":"Dữ liệu được cập nhật gần thời điểm phân tích và còn giá trị sử dụng."},{"key":"C","text":"Dữ liệu có cùng giá trị khi đối chiếu giữa các nguồn thu thập."},{"key":"D","text":"Dữ liệu hợp lý về mặt lâm sàng và không mâu thuẫn với giới hạn đã biết."}],"answer":"D","explain":"Plausibility xem dữ liệu có hợp lý trong bối cảnh thực tế hay không, chẳng hạn tuổi không âm."},{"id":"4.2.","text":"Dữ liệu khuyết loại MNAR khó nhất vì sao?","options":[{"key":"A","text":"Vì nguyên nhân khuyết có thể liên quan đến chính giá trị không quan sát được."},{"key":"B","text":"Vì dữ liệu MNAR khó diễn giải trong nghiên cứu y sinh nếu thiếu thông tin bổ sung."},{"key":"C","text":"Vì các phương pháp xử lý dữ liệu khuyết có thể cho kết quả khác nhau."},{"key":"D","text":"Vì MNAR thường xảy ra khi dữ liệu được lưu trong một hệ thống cũ."}],"answer":"A","explain":"Khi cơ chế khuyết gắn với giá trị bị khuyết, dữ liệu quan sát khó đủ để suy ra cơ chế."},{"id":"4.3.","text":"Vì sao không nên dùng mean imputation như một cách mặc định?","options":[{"key":"A","text":"Vì giá trị trung bình khó tính được từ dữ liệu số có phân phối lệch trong một số trường hợp."},{"key":"B","text":"Vì cách này có thể làm giảm phương sai và bóp méo quan hệ giữa các biến."},{"key":"C","text":"Vì mean imputation thường phù hợp với biến phân loại và không dùng cho biến số."},{"key":"D","text":"Vì điền trung bình có thể làm giảm số lượng quan sát còn lại trong phân tích."}],"answer":"B","explain":"Điền cùng một giá trị cho nhiều ô có thể làm dữ liệu trông ổn định hơn thực tế."},{"id":"4.4.","text":"Tình huống: Bệnh nhân nặng thường không đo được một xét nghiệm vì không lấy được mẫu. Đây là loại khuyết nào?","options":[{"key":"A","text":"MCAR, vì việc lấy mẫu không liên quan đến tình trạng bệnh của người bệnh."},{"key":"B","text":"MAR, vì dùng các giá trị đã quan sát có thể giúp xác định nhiều nguyên nhân."},{"key":"C","text":"MNAR, vì khả năng khuyết có thể liên quan đến chính tình trạng bệnh."},{"key":"D","text":"Không phải dữ liệu khuyết, vì xét nghiệm chưa từng được thực hiện trên mẫu đó."}],"answer":"C","explain":"Cơ chế khuyết có thể liên quan đến mức độ bệnh; cần ghi giả định và phân tích độ nhạy."}]},"headers":[],"relativePath":"course/module-4-quality/quiz.md","filePath":"course/module-4-quality/quiz.md"}'),l={name:"course/module-4-quality/quiz.md"};function o(r,n,s,k,m,p){const h=e("Quiz",!0);return c(),u("div",null,[n[0]||(n[0]=t("h1",{id:"quiz-—-bai-4",tabindex:"-1"},[a("Quiz — Bài 4 "),t("a",{class:"header-anchor",href:"#quiz-—-bai-4","aria-label":'Permalink to "Quiz — Bài 4"'},"​")],-1)),g(h)])}const x=i(l,[["render",o]]);export{d as __pageData,x as default};
